[.tooling/components/apps/mkdocs-platform/k8s/README.md#gitops-integration]

### GitOps Integration

```yaml
# Example GitHub Actions workflow
- name: Deploy to Kubernetes
  run: |
    export ENVIRONMENT=${{ github.ref_name == 'main' && 'prod' || 'dev' }}
    export ECR_REGISTRY_URL=${{ secrets.ECR_REGISTRY_URL }}
    export ECR_REPOSITORY_NAME=${{ secrets.ECR_REPOSITORY_NAME }}
    export IMAGE_TAG=${{ github.sha }}
    source env-$ENVIRONMENT
    ./k8s/deploy.sh deploy
```
